export function findWilayaByCode(code: string) {
  return ALGERIA_WILAYAS.find((wilaya) => wilaya.code === code);
}

export function findCommuneInWilaya(wilayaCode: string, communeName: string) {
  const wilaya = findWilayaByCode(wilayaCode);
  if (!wilaya) return null;
  return wilaya.communes.find((commune) => commune.name === communeName) ?? null;
}


